// Code node "Build provider request" (LLM gateway). Mode: Run Once for All Items.
//
// The gateway is the only place that knows a provider's wire format, so swapping Gemini for
// another provider is a change here and in one HTTP node's credential. Callers send a
// provider-neutral request: { purpose, model, system, prompt, schema, temperature,
// max_output_tokens, prompt_version }.
//
// The daily request budget is enforced before the call. Gemini's free tier has a
// requests-per-day cap, and spending it on a runaway loop would block the demo for the rest
// of the day.
//
// A caller may send several requests at once (one item each). The HTTP node then sends them
// concurrently, llm_concurrency at a time, and waits between those groups so the account stays
// under llm_rpm (DECISIONS AD29). Every request is checked against the budget on its own.

const GEMINI_BASE = 'https://generativelanguage.googleapis.com/v1beta/models';

function geminiCall(request) {
  return {
    url: `${GEMINI_BASE}/${encodeURIComponent(request.model)}:generateContent`,
    body: {
      systemInstruction: { parts: [{ text: request.system }] },
      contents: [{ role: 'user', parts: [{ text: request.prompt }] }],
      generationConfig: {
        temperature: request.temperature ?? 0,
        maxOutputTokens: request.max_output_tokens ?? 8192,
        responseMimeType: 'application/json',
        responseJsonSchema: request.schema,
      },
    },
  };
}

function build(request, config, callsToday) {
  const base = {
    purpose: request.purpose,
    prompt_version: request.prompt_version ?? null,
    provider: config.llm_provider,
    model: request.model,
    max_retries: Number(config.llm_max_retries),
  };
  // Run from its own canvas the gateway has no request; say so instead of calling the provider.
  if (!request.model || !request.prompt) {
    return {
      ...base,
      within_budget: false,
      ok: false,
      calls: 0,
      error: 'no request to send: the gateway is called by Workflow A, Workflow B and the warm step '
        + '(run one of those, or pin a { purpose, model, system, prompt, schema } item on "Called by A or B")',
    };
  }
  const budget = Number(config.llm_rpd);
  if (callsToday >= budget) {
    return {
      ...base,
      within_budget: false,
      ok: false,
      calls: 0,
      error: `daily LLM budget reached: ${callsToday} of ${budget} requests used (LLM_RPD)`,
    };
  }
  if (config.llm_provider !== 'gemini') {
    // The gateway's interface is provider-neutral, but only the Gemini branch is wired so far.
    return { ...base, within_budget: false, ok: false, calls: 0, error: `provider ${config.llm_provider} is not wired` };
  }
  return { ...base, within_budget: true, ...geminiCall(request) };
}

// How many requests go out together, and how long to wait between groups to respect llm_rpm.
function pacing(config) {
  const concurrency = Math.max(1, Math.floor(Number(config.llm_concurrency) || 1));
  const rpm = Number(config.llm_rpm);
  const interval = rpm > 0 ? Math.ceil((60000 * concurrency) / rpm) : 0;
  return { batch_size: concurrency, batch_interval_ms: interval };
}

// ---- n8n entry point ----
const config = $('Load app_config').first().json.config;
const callsToday = Number($input.first().json.calls_today ?? 0);
const pace = pacing(config);
const sentMs = Date.now();
return $('Called by A or B').all().map((item, index) => ({
  json: { request_index: index, ...build(item.json, config, callsToday + index), ...pace, sent_ms: sentMs },
}));

// Code node "Parse provider response" (LLM gateway). Mode: Run Once for All Items.
//
// Decides one of three outcomes for each provider response:
//   * ok: valid JSON matching the schema the caller asked for;
//   * retry: rate limited (429), server error (5xx) or network failure, while attempts remain.
//     The wait comes from the provider's RetryInfo or Retry-After when given, otherwise it is
//     exponential (4s, 8s, 16s ... capped at 60s);
//   * error: anything else, or retries exhausted.
// This node runs once per attempt (a pass over every request still in flight), so the attempt
// number is n8n's run index + 1. Pass 0 answers what "Within daily budget?" let through, later
// passes what "Back off" sent again; the HTTP node keeps item order, so response i belongs to
// request i of the same pass. duration_ms runs from the pass's start to its last response.

function retryDelaySeconds(response, attempt) {
  const details = response.body?.error?.details ?? [];
  const info = details.find((d) => String(d['@type'] ?? '').endsWith('RetryInfo'));
  const fromBody = info ? parseFloat(String(info.retryDelay)) : NaN;
  const fromHeader = parseFloat(response.headers?.['retry-after'] ?? '');
  const hinted = Number.isFinite(fromBody) ? fromBody : fromHeader;
  if (Number.isFinite(hinted) && hinted > 0) return Math.min(Math.ceil(hinted), 60);
  return Math.min(2 ** (attempt + 1), 60);
}

function parseGemini(body) {
  const usage = body.usageMetadata ?? {};
  const tokens = {
    tokens_in: usage.promptTokenCount ?? 0,
    tokens_out: (usage.candidatesTokenCount ?? 0) + (usage.thoughtsTokenCount ?? 0),
  };
  if (body.promptFeedback?.blockReason) {
    return { ...tokens, error: `prompt blocked: ${body.promptFeedback.blockReason}` };
  }
  const candidate = body.candidates?.[0];
  if (!candidate) return { ...tokens, error: 'no candidates in response' };
  if (candidate.finishReason && candidate.finishReason !== 'STOP') {
    return { ...tokens, error: `generation stopped: ${candidate.finishReason}` };
  }
  const text = (candidate.content?.parts ?? []).map((part) => part.text ?? '').join('');
  try {
    return { ...tokens, data: JSON.parse(text) };
  } catch (err) {
    return { ...tokens, error: `response was not valid JSON: ${err.message}` };
  }
}

function decide(request, response, attempt) {
  const status = response.statusCode ?? 0;
  const common = {
    request_index: request.request_index,
    batch_size: request.batch_size,
    batch_interval_ms: request.batch_interval_ms,
    purpose: request.purpose,
    prompt_version: request.prompt_version,
    provider: request.provider,
    model: request.model,
    url: request.url,
    body: request.body,
    max_retries: request.max_retries,
    attempt,
    http_status: status,
  };
  if (status === 200) {
    const parsed = parseGemini(response.body ?? {});
    if (parsed.error) return { ...common, ...parsed, ok: false, retry: false, outcome: 'error' };
    return { ...common, ...parsed, ok: true, retry: false, outcome: 'ok', error: null };
  }
  const retryable = status === 0 || status === 429 || status >= 500;
  const message =
    response.body?.error?.message ?? response.error?.message ?? `HTTP ${status || 'request failed'}`;
  const outcome = status === 429 ? 'rate_limited' : 'error';
  if (retryable && attempt < request.max_retries) {
    return {
      ...common, ok: false, retry: true, outcome, tokens_in: 0, tokens_out: 0,
      wait_seconds: retryDelaySeconds(response, attempt), error: message,
    };
  }
  return { ...common, ok: false, retry: false, outcome, tokens_in: 0, tokens_out: 0, error: message };
}

// ---- n8n entry point ----
const pass = $runIndex;
const sent = pass === 0 ? $('Within daily budget?').all(0, 0) : $('Back off').all(0, pass - 1);
const now = Date.now();
return $input.all().map((response, i) => {
  const request = sent[i].json;
  const outcome = decide(request, response.json, pass + 1);
  return { json: { ...outcome, duration_ms: Math.max(0, now - (request.sent_ms ?? now)) } };
});

// Code node "Restore response" (LLM gateway). Mode: Run Once for All Items.
//
// "Log LLM call" is a Postgres node, so its output is the inserted rows. This puts the parsed
// provider responses back on the main path for the retry decision. $('…').all() returns the
// latest run, which is the pass just logged. Requests to retry wait together (one Wait node),
// as long as the longest delay any of them was given, and their next pass starts after it.

const items = $('Parse provider response').all().map((item) => item.json);
const wait = Math.max(0, ...items.filter((item) => item.retry).map((item) => item.wait_seconds ?? 0));
const resend = Date.now() + wait * 1000;
return items.map((item) => ({ json: item.retry ? { ...item, wait_seconds: wait, sent_ms: resend } : item }));

// Code node "Return result" (LLM gateway). Mode: Run Once for All Items.
//
// The gateway's only output: one item per request, in request order, in the same shape
// whether the call succeeded, failed or was refused by the budget guard. Callers branch on `ok`,
// and record `calls` and the tokens in their own metrics. The request URL and body never leave
// the gateway.
//
// A request ends either at "Within daily budget?" (refused) or at "Retry?" (answered, or out of
// retries), in whichever pass it finished. This node runs once for each pass that finished
// something, and n8n hands the caller only its last run, so every run reads all of them.

const MAX_PASSES = 20;

function result(item) {
  return {
    request_index: item.request_index ?? 0,
    ok: item.ok === true,
    data: item.ok === true ? item.data : null,
    error: item.ok === true ? null : item.error ?? 'unknown error',
    purpose: item.purpose,
    prompt_version: item.prompt_version ?? null,
    provider: item.provider,
    model: item.model,
    calls: item.attempt ?? item.calls ?? 0,
    tokens_in: item.tokens_in ?? 0,
    tokens_out: item.tokens_out ?? 0,
  };
}

// Items one node put on one branch in one run; null once that run doesn't exist.
function ended(node, branch, run) {
  try {
    return $(node).all(branch, run).map((item) => item.json);
  } catch (error) {
    return /not found|hasn't been executed/.test(String(error?.message)) ? null : [];
  }
}

function finished() {
  const byRequest = new Map();
  for (const item of ended('Within daily budget?', 1, 0) ?? []) byRequest.set(item.request_index, item);
  for (let run = 0; run < MAX_PASSES; run += 1) {
    const items = ended('Retry?', 1, run);
    if (items === null) break;
    for (const item of items) byRequest.set(item.request_index, item);
  }
  return [...byRequest.values()].sort((a, b) => (a.request_index ?? 0) - (b.request_index ?? 0));
}

// ---- n8n entry point ----
return finished().map((item) => ({ json: result(item) }));
